pub interface Describable {
    fn describe(self) -> String
}
pub record User { name: String }
impl Describable for User {
    fn describe(self) -> String {
        "a user"
    }
}
pub type AppError = Failed(String)
pub fn main() -> Result<(), AppError> {
    let u = User { name: "a" }
    let text = u.describe()
    return Ok(())
}

